3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
8	
9	/**
10	 * Step of {@code POST /api/owners} that rejects a create when the owner's city already contains 50
11	 * or more owners, throwing {@link CityAtCapacityException} (handled as 409 Conflict). Cities are
12	 * compared case-insensitively with trimmed whitespace. Runs after {@link RequireOwnerFields} has
13	 * published the validated body and before {@link BuildOwner}/{@link SaveOwner} persist the new
14	 * owner.
15	 */
16	public class RequireCityCapacity {
17	
18	    /** Maximum number of owners permitted in a single city. */
19	    private static final int CITY_CAPACITY = 50;
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws CityAtCapacityException {
23	        String city = normalize(request.getCity());
24	        int count = 0;
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (city.equals(normalize(existing.getCity()))) {
27	                count++;
28	            }
29	        }
30	        if (count >= CITY_CAPACITY) {
31	            throw new CityAtCapacityException(
32	                    "City " + request.getCity() + " already has the maximum of " + CITY_CAPACITY
33	                            + " owners");
34	        }
35	    }
36	
37	    private static String normalize(String city) {
38	        return city == null ? "" : city.trim().toLowerCase();
39	    }
40	}
