3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DailyRegistrationLimitException;
10	
11	/**
12	 * Step of {@code POST /api/owners} that rejects a create when 100 or more owners have already been
13	 * registered on the same adjusted business day (by {@link Owner#getRegistrationDate()}), throwing
14	 * {@link DailyRegistrationLimitException} (handled as 429 Too Many Requests). The business day is
15	 * the effective registration date (supplied on the request or defaulted to today) rolled forward
16	 * off a weekend to the next Monday (see {@link BusinessDay}), matching the date
17	 * {@link BuildOwner}/{@link SaveOwner} will store for the new owner.
18	 */
19	public class RequireDailyRegistrationLimit {
20	
21	    /** Maximum number of owners permitted to register in a single day. */
22	    private static final int DAILY_LIMIT = 100;
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws DailyRegistrationLimitException {
26	        LocalDate businessDay = BusinessDay.effectiveRegistrationDate(request.getRegistrationDate());
27	        int count = 0;
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (businessDay.equals(existing.getRegistrationDate())) {
30	                count++;
31	            }
32	        }
33	        if (count >= DAILY_LIMIT) {
34	            throw new DailyRegistrationLimitException(
35	                    "The daily limit of " + DAILY_LIMIT + " owner registrations has been reached");
36	        }
37	    }
38	}
