3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is
9	 * the upper-cased first three letters of city, LAST3 the upper-cased first three letters of lastName
10	 * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the owners already in that
11	 * city (e.g. {@code SYD-SMI-0007}). Runs before {@link SaveOwner} so the owner being created is not
12	 * itself counted.
13	 */
14	public class AssignCustomerCode {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String city = owner.getCity();
18	        String cityPrefix = prefix(city);
19	        String lastPrefix = prefix(owner.getLastName());
20	        long sequence = ownerRepository.findAll().stream()
21	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
22	            .count() + 1;
23	        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence));
24	    }
25	
26	    private static String prefix(String value) {
27	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
28	    }
29	}
