27	        if (telephone == null) {
28	            throw invalid();
29	        }
30	        // Strip spaces, dashes and brackets; any other non-digit survives and fails the check below.
31	        String stripped = telephone.replaceAll("[\\s()\\-]", "");
32	        String e164;
