22	     * @throws InvalidEmailException when a non-blank value is not a valid address.
23	     */
24	    static String normalize(String email) throws InvalidEmailException {
25	        if (email == null || email.isBlank()) {
26	            return null;
27	        }
28	        String normalized = email.trim().toLowerCase(Locale.ROOT);
29	        if (!EMAIL.matcher(normalized).matches()) {
30	            throw new InvalidEmailException("Email must be a syntactically valid address");
31	        }
32	        return normalized;
