2	
3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
6	
7	/**
8	 * Postcode validation for pet owners. A postcode is optional; when present it must be a 4-digit
9	 * number. When the owner's city maps to a known region (see {@link Locality}) the postcode must
10	 * fall inside that region's fixed inclusive range: {@code NSW 2000-2099}, {@code VIC 3000-3099},
11	 * {@code QLD 4000-4099}. A city with no known region ({@code UNKNOWN}) accepts any 4-digit
12	 * postcode. Derived purely from the fixed region table, so it is seed-independent.
13	 */
14	public final class Postcode {
15	
16	    /** Region -> inclusive 4-digit postcode range {low, high}. Fixed, pinned reference data. */
17	    private static final Map<String, int[]> REGION_RANGES = Map.of(
18	            "NSW", new int[] {2000, 2099},
19	            "VIC", new int[] {3000, 3099},
20	            "QLD", new int[] {4000, 4099});
21	
22	    private Postcode() {
23	    }
24	
25	    /**
26	     * Validates the supplied postcode for the given city. A {@code null} or blank postcode is
27	     * treated as absent and passes (postcode is optional). Otherwise it must be exactly 4 digits,
28	     * and when the city's region has a known range the postcode must be within it.
29	     *
30	     * @throws InvalidPostcodeException when the postcode is malformed or out of range for the
31	     * city's region.
32	     */
33	    public static void validate(String postcode, String city) throws InvalidPostcodeException {
34	        if (postcode == null || postcode.isBlank()) {
35	            return; // absent: optional
36	        }
37	        if (!postcode.matches("[0-9]{4}")) {
38	            throw new InvalidPostcodeException("Postcode must be 4 digits: " + postcode);
39	        }
40	        int[] range = REGION_RANGES.get(Locality.of(city));
41	        if (range == null) {
42	            return; // unknown region: any 4-digit postcode accepted
43	        }
44	        int value = Integer.parseInt(postcode);
45	        if (value < range[0] || value > range[1]) {
46	            throw new InvalidPostcodeException("Postcode " + postcode + " is not valid for city "
47	                    + city + " (expected " + range[0] + "-" + range[1] + ")");
48	        }
49	    }
50	}
