3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * The registration date must fall on a business day. Computes the EFFECTIVE registration date for a
8	 * create: the date supplied on the request, or the server's current date when none was supplied,
9	 * rolled forward to the next Monday when it lands on a Saturday or Sunday. Every value derived from
10	 * the registration date (the membership number's year segment, the daily create-limit's day) uses
11	 * this adjusted date.
12	 */
13	public final class BusinessDay {
14	
15	    private BusinessDay() {
16	    }
17	
18	    /**
19	     * The effective registration date for a create: {@code supplied} when present, otherwise the
20	     * server's current date, rolled forward off a weekend to the next Monday.
21	     */
22	    public static LocalDate effectiveRegistrationDate(LocalDate supplied) {
23	        return rollForward(supplied != null ? supplied : LocalDate.now());
24	    }
25	
26	    /** Rolls a Saturday or Sunday forward to the next Monday; a business day is returned unchanged. */
27	    public static LocalDate rollForward(LocalDate date) {
28	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
29	            date = date.plusDays(1);
30	        }
31	        return date;
32	    }
33	}
